### 3. detail::basic_sha512_half_hasher

```cpp
template <bool Secure>
struct basic_sha512_half_hasher
{
private:
    sha512_hasher h_;

public:
    static constexpr auto const endian = boost::endian::order::big;
    using result_type = uint256;

    ~basic_sha512_half_hasher()
    {
        erase(std::integral_constant<bool, Secure>{});
    }

    void operator()(void const* data, std::size_t size) noexcept
    {
        h_(data, size);
    }

    explicit operator result_type() noexcept
    {
        auto const digest = sha512_hasher::result_type(h_);
        return result_type::fromVoid(digest.data());
    }

private:
    inline void erase(std::false_type) {}
    inline void erase(std::true_type)
    {
        secure_erase(&h_, sizeof(h_));
    }
};
```
- This struct wraps a sha512_hasher (which implements SHA-512).
- Data is fed into the hasher via operator()(void const*, std::size_t).
- When converted to result_type (uint256), it finalizes the SHA-512 hash and returns the first 32 bytes as a uint256.
- If Secure is true, the hasher's memory is securely erased on destruction.

